  "dependency-injection.page.scss": ".layout {\n  display: grid;\n  gap: 16px;\n  grid-template-columns: repeat(auto-fit, minmax(min(100%, 360px), 1fr));\n  align-items: start;\n}\n\ndl {\n  display: grid;\n  grid-template-columns: auto 1fr;\n  gap: 4px 12px;\n  margin: 0;\n\n  dd {\n    margin: 0;\n  }\n}\n\nh4 {\n  margin: 16px 0 4px;\n  font: var(--mat-sys-title-small);\n}\n\n.flags {\n  list-style: none;\n  margin: 0;\n  padding: 0;\n}\n\na.active {\n  background: var(--mat-sys-secondary-container);\n  color: var(--mat-sys-on-secondary-container);\n}\n\n.outlet {\n  min-height: 140px;\n}\n",
  "dependency-injection.page.ts": "import { DatePipe } from '@angular/common';\nimport { Component, inject } from '@angular/core';\nimport { MatButtonModule } from '@angular/material/button';\nimport { MatIconModule } from '@angular/material/icon';\nimport { MatSlideToggleModule } from '@angular/material/slide-toggle';\nimport { RouterLink, RouterLinkActive, RouterOutlet } from '@angular/router';\nimport { AppConfigStore } from '../../core/config/app-config.store';\nimport { DemoPage } from '../../shared/demo-page/demo-page';\nimport { EventLog } from '../../shared/event-log/event-log';\nimport { SNIPPETS } from './dependency-injection.snippets';\nimport { LifecycleLogStore } from './lifecycle-log.store';\n\n/** Video 022 – Dependency injection & service lifecycle. */\n@Component({\n  selector: 'app-dependency-injection-page',\n  imports: [\n    DatePipe,\n    DemoPage,\n    EventLog,\n    MatButtonModule,\n    MatIconModule,\n    MatSlideToggleModule,\n    RouterLink,\n    RouterLinkActive,\n    RouterOutlet,\n  ],\n  templateUrl: './dependency-injection.page.html',\n  styleUrl: './dependency-injection.page.scss',\n})\nexport class DependencyInjectionPage {\n  readonly config = inject(AppConfigStore);\n  readonly log = inject(LifecycleLogStore);\n  readonly snippets = SNIPPETS;\n}\n",
  "dependency-injection.routes.ts": "import { inject, provideEnvironmentInitializer } from '@angular/core';\nimport { Routes } from '@angular/router';\nimport { DependencyInjectionPage } from './dependency-injection.page';\nimport { featureFlagGuard } from './feature-flag.guard';\nimport { FEATURE_NAME, FeatureSessionService } from './feature-session.service';\nimport { FeatureView } from './feature-view';\nimport { LifecycleLogStore } from './lifecycle-log.store';\n\nfunction featureProviders(name: string) {\n  return [\n    { provide: FEATURE_NAME, useValue: name },\n    FeatureSessionService,\n    // Runs once when this route's EnvironmentInjector is created.\n    provideEnvironmentInitializer(() =>\n      inject(LifecycleLogStore).log(`environment initializer: injector for ${name} created`),\n    ),\n  ];\n}\n\nexport const routes: Routes = [\n  {\n    path: '',\n    component: DependencyInjectionPage,\n    children: [\n      { path: 'feature-a', component: FeatureView, providers: featureProviders('Feature A') },\n      {\n        path: 'feature-b',\n        component: FeatureView,\n        canActivate: [featureFlagGuard],\n        data: { flag: 'featureB' },\n        providers: featureProviders('Feature B'),\n      },\n    ],\n  },\n];\n",
  "feature-flag.guard.ts": "import { inject } from '@angular/core';\nimport { CanActivateFn, Router } from '@angular/router';\nimport { AppConfigStore } from '../../core/config/app-config.store';\nimport { LifecycleLogStore } from './lifecycle-log.store';\n\n/** Functional guard with inject(): reads a feature flag from the startup config. */\nexport const featureFlagGuard: CanActivateFn = (route) => {\n  const flag = String(route.data['flag'] ?? '');\n  if (inject(AppConfigStore).isFeatureEnabled(flag)) {\n    return true;\n  }\n  inject(LifecycleLogStore).log(`guard: \"${flag}\" is disabled – navigation blocked`);\n  return inject(Router).createUrlTree(['/videos/022-dependency-injection']);\n};\n",
  "feature-session.service.ts": "import { DestroyRef, Injectable, InjectionToken, inject, signal } from '@angular/core';\nimport { LifecycleLogStore } from './lifecycle-log.store';\n\nexport const FEATURE_NAME = new InjectionToken<string>('FEATURE_NAME');\n\nlet instances = 0;\n\n/**\n * Scoped to a route via `providers`. Each route injector gets its own instance; with\n * withAutoCleanupInjectors() it is destroyed when the route becomes inactive.\n */\n@Injectable()\nexport class FeatureSessionService {\n  readonly #log = inject(LifecycleLogStore);\n  readonly feature = inject(FEATURE_NAME);\n  readonly instanceId = ++instances;\n  readonly startedAt = new Date();\n  readonly secondsAlive = signal(0);\n\n  constructor() {\n    this.#log.log(`FeatureSessionService #${this.instanceId} created for ${this.feature}`);\n    const timer = setInterval(() => this.secondsAlive.update((s) => s + 1), 1000);\n    // DestroyRef of the route's EnvironmentInjector: cleanup for timers, sockets, …\n    inject(DestroyRef).onDestroy(() => {\n      clearInterval(timer);\n      this.#log.log(\n        `FeatureSessionService #${this.instanceId} destroyed (${this.feature}) – timer cleared`,\n      );\n    });\n  }\n}\n",
  "feature-view.ts": "import { DatePipe } from '@angular/common';\nimport { Component, inject } from '@angular/core';\nimport { FeatureSessionService } from './feature-session.service';\n\n@Component({\n  selector: 'app-feature-view',\n  imports: [DatePipe],\n  template: `\n    <h4>{{ session.feature }}</h4>\n    <dl>\n      <dt>Service instance</dt>\n      <dd>#{{ session.instanceId }}</dd>\n      <dt>Started</dt>\n      <dd>{{ session.startedAt | date: 'HH:mm:ss' }}</dd>\n      <dt>Alive for</dt>\n      <dd>{{ session.secondsAlive() }} s</dd>\n    </dl>\n  `,\n  styles: `\n    :host {\n      display: block;\n      padding: 16px;\n      border-radius: var(--mat-sys-corner-medium);\n      background: var(--mat-sys-surface);\n      border: 1px solid var(--mat-sys-outline-variant);\n    }\n    h4 {\n      margin: 0 0 8px;\n      font: var(--mat-sys-title-medium);\n    }\n    dl {\n      display: grid;\n      grid-template-columns: auto 1fr;\n      gap: 4px 12px;\n      margin: 0;\n    }\n    dd {\n      margin: 0;\n      font-variant-numeric: tabular-nums;\n    }\n  `,\n})\nexport class FeatureView {\n  readonly session = inject(FeatureSessionService);\n}\n",
