  "app.config.ts": "import { provideHttpClient, withFetch, withInterceptors } from '@angular/common/http';\nimport {\n  ApplicationConfig,\n  inject,\n  provideAppInitializer,\n  provideBrowserGlobalErrorListeners,\n  provideEnvironmentInitializer,\n  provideZonelessChangeDetection,\n} from '@angular/core';\nimport { MatIconRegistry } from '@angular/material/icon';\nimport { EVENT_MANAGER_PLUGINS } from '@angular/platform-browser';\nimport {\n  TitleStrategy,\n  provideRouter,\n  withAutoCleanupInjectors,\n  withComponentInputBinding,\n  withInMemoryScrolling,\n  withRouterConfig,\n  withViewTransitions,\n} from '@angular/router';\nimport { routes } from './app.routes';\nimport { AppConfigStore } from './core/config/app-config.store';\nimport { DebounceEventPlugin, ThrottleEventPlugin } from './core/events/timing-event.plugins';\nimport { fakeBackendInterceptor } from './core/fake-backend/fake-backend.interceptor';\nimport { authInterceptor } from './core/http/auth.interceptor';\nimport { errorInterceptor } from './core/http/error.interceptor';\nimport { loadingInterceptor } from './core/http/loading.interceptor';\nimport { loggingInterceptor } from './core/http/logging.interceptor';\nimport { AppTitleStrategy } from './core/title.strategy';\nimport { ViewTransitionSettingsStore } from './core/view-transitions/view-transition-settings.store';\n\nexport const appConfig: ApplicationConfig = {\n  providers: [\n    provideBrowserGlobalErrorListeners(),\n    // Zoneless is the default since v21 – set explicitly so video 011 can point at it.\n    provideZonelessChangeDetection(),\n    provideRouter(\n      routes,\n      withComponentInputBinding(),\n      withViewTransitions({\n        skipInitialTransition: true,\n        onViewTransitionCreated: (info) => inject(ViewTransitionSettingsStore).onCreated(info),\n      }),\n      withInMemoryScrolling({ scrollPositionRestoration: 'enabled', anchorScrolling: 'enabled' }),\n      withRouterConfig({ paramsInheritanceStrategy: 'always' }),\n      // 22.2: destroy route injectors (route `providers`) once their route is inactive.\n      withAutoCleanupInjectors(),\n    ),\n    provideHttpClient(\n      withFetch(),\n      // Order matters: the fake backend answers last, after auth/logging/loading/error.\n      withInterceptors([\n        authInterceptor,\n        loggingInterceptor,\n        loadingInterceptor,\n        errorInterceptor,\n        fakeBackendInterceptor,\n      ]),\n    ),\n    provideAppInitializer(() => inject(AppConfigStore).load()),\n    { provide: TitleStrategy, useClass: AppTitleStrategy },\n    { provide: EVENT_MANAGER_PLUGINS, useClass: DebounceEventPlugin, multi: true },\n    { provide: EVENT_MANAGER_PLUGINS, useClass: ThrottleEventPlugin, multi: true },\n    provideEnvironmentInitializer(() =>\n      inject(MatIconRegistry).setDefaultFontSetClass('material-symbols-outlined'),\n    ),\n  ],\n};\n",
  "core/config/app-config.store.ts": "import { HttpClient, HttpContext } from '@angular/common/http';\nimport { Service, computed, inject, signal } from '@angular/core';\nimport { firstValueFrom } from 'rxjs';\nimport { AppConfig } from '../fake-backend/fake-db';\nimport { SKIP_ERROR_HANDLING } from '../http/http-context';\n\nexport const FALLBACK_CONFIG: AppConfig = {\n  appName: 'Angular 22 Demos',\n  apiVersion: 'offline',\n  environment: 'fallback',\n  features: { featureA: true, featureB: true, betaWidgets: false },\n};\n\n/** Startup configuration loaded once via provideAppInitializer (video 022). */\n@Service()\nexport class AppConfigStore {\n  readonly #http = inject(HttpClient);\n  readonly #config = signal<AppConfig>(FALLBACK_CONFIG);\n  readonly #loadMs = signal<number | null>(null);\n  readonly #source = signal<'server' | 'fallback'>('fallback');\n\n  readonly config = this.#config.asReadonly();\n  readonly loadMs = this.#loadMs.asReadonly();\n  readonly source = this.#source.asReadonly();\n  readonly loadedAt = signal<Date | null>(null);\n\n  isFeatureEnabled(name: string): boolean {\n    return this.#config().features[name] ?? false;\n  }\n\n  readonly featureList = computed(() => Object.entries(this.#config().features));\n\n  /** Runtime override of a feature flag (used by the guard demo in video 022). */\n  setFeature(name: string, enabled: boolean): void {\n    this.#config.update((config) => ({\n      ...config,\n      features: { ...config.features, [name]: enabled },\n    }));\n  }\n\n  async load(): Promise<void> {\n    const started = performance.now();\n    try {\n      const config = await firstValueFrom(\n        this.#http.get<AppConfig>('/api/config', {\n          context: new HttpContext().set(SKIP_ERROR_HANDLING, true),\n        }),\n      );\n      this.#config.set(config);\n      this.#source.set('server');\n    } catch {\n      this.#config.set(FALLBACK_CONFIG);\n      this.#source.set('fallback');\n    } finally {\n      this.#loadMs.set(Math.round(performance.now() - started));\n      this.loadedAt.set(new Date());\n    }\n  }\n}\n",
